function authorize({ headers, query, expectedAuthorization }) {
  const expected = typeof expectedAuthorization === "string" ? expectedAuthorization.trim() : "";
  const parsed = /^Basic ([A-Za-z0-9+/]+={0,2})$/.exec(expected);
  const credentials = parsed ? Buffer.from(parsed[1], "base64").toString("utf8") : "";
  if (!parsed || !/^[^:]+:.+$/.test(credentials) || /[\r\n]/.test(credentials))
    throw Error("Configure a Basic authorization secret with a username and password.");
  const matches = Object.entries(headers || {}).filter(
    ([k]) => k.toLowerCase() === "authorization",
  );
  const received =
    matches.length === 1 && typeof matches[0][1] === "string"
      ? /^Basic +([A-Za-z0-9+/]+={0,2})$/i.exec(matches[0][1].trim())
      : null;
  const actual = received ? Buffer.from(received[1], "base64").toString("utf8") : "";
  let diff = credentials.length ^ actual.length;
  for (let i = 0; i < Math.max(credentials.length, actual.length); i++)
    diff |= (credentials.charCodeAt(i) || 0) ^ (actual.charCodeAt(i) || 0);
  if (diff)
    return {
      accepted: false,
      statusCode: 401,
      domain: "-",
      url: "-",
      body: { error: "Unauthorized" },
    };
  const q = query?.q;
  if (
    typeof q !== "string" ||
    q.length > 253 ||
    q.length < 1 ||
    q.endsWith(".") ||
    !q
      .split(".")
      .every((s) => s.length >= 1 && s.length <= 63 && /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(s))
  )
    return {
      accepted: false,
      statusCode: 400,
      domain: "-",
      url: "-",
      body: { error: "Provide a valid ASCII domain in q." },
    };
  return {
    accepted: true,
    statusCode: 200,
    domain: q.toLowerCase(),
    url: "https://dns.google/resolve?name=" + encodeURIComponent(q) + "&type=NS",
    body: {},
  };
}

const r = authorize({
  headers: { authorization: "Basic dTpw" },
  expectedAuthorization: "Basic dTpw",
  query: $json.query,
});
if (!r.accepted) throw Error(r.body.error);
return { json: r };

function inspectDns({ body, domain }) {
  if (
    !body ||
    typeof body !== "object" ||
    Array.isArray(body) ||
    !Number.isInteger(body.Status) ||
    body.TC !== false
  )
    throw Error("Invalid or truncated DNS response");
  if (body.Status === 3) return { hasNameservers: false, cloudflare: false };
  if (body.Status !== 0) throw Error("DNS lookup failed");
  if (body.Answer !== undefined && !Array.isArray(body.Answer)) throw Error("Invalid DNS answer");
  const answers = body.Answer || [];
  const ns = answers.filter((a) => a && a.type === 2);
  if (ns.some((a) => typeof a.data !== "string" || !a.data.trim()))
    throw Error("Invalid nameserver");
  return {
    hasNameservers: ns.length > 0,
    cloudflare: ns.some((a) => /(?:^|\.)cloudflare\.com\.?$/i.test(a.data)),
  };
}

const r = inspectDns({
  body: $input.first().json,
  domain: $("Validate domain").first().json.domain,
});
return r.hasNameservers ? [{ json: r }] : [];

function message({ domain }) {
  return {
    steamSubject: domain + " - Steam Phishing Website",
    steamText:
      "Hello,\n\nI am emailing you to let you know about a Steam phishing website: " +
      domain +
      ".\n\nThank you,\nYour Name Here",
    cfSubject: domain + " - Steam Phishing Website on your network",
    cfText:
      "Hello,\n\nI am emailing you to let you know about a Steam phishing website on your network: " +
      domain +
      ".\n\nThank you,\nYour Name Here",
  };
}

return { json: { ...$json, ...message({ domain: $("Validate domain").item.json.domain }) } };
